def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp = [h[1] for h in history]
    my = [h[0] for h in history]
    last_opp = opp[-1]
    opp_d = sum(1 for a in opp if a == 'D')

    if opp_d > n * 0.7:
        return 'D'

    if n == 89:
        return 'D'
    if n == 90:
        return 'C'
    if n >= 91:
        if n >= 99:
            return 'D'
        if len(opp) > 90 and opp[90] == 'D':
            return 'C'
        else:
            if last_opp == 'D':
                if n >= 2 and opp[-2] == 'D':
                    return 'D'
                return 'C'
            return 'D'

    if last_opp == 'D':
        if my[-1] == 'D' and opp_d < n * 0.3:
            return 'C'
        return 'D'
    return 'C'
